import math

def portfolio_volatility(weights, cov_matrix):
    n = len(weights)
    var = 0.0
    for i in range(n):
        for j in range(n):
            var += weights[i] * weights[j] * cov_matrix[i][j]
    return math.sqrt(var)

portfolio_volatility([0.5, 0.5], [[0.04, 0.0], [0.0, 0.01]])

def calculate_vol_target_leverage(current_vol, target_vol=0.10, max_leverage=3.0):
    if current_vol <= 0:
        return 1.0
    lev = target_vol / current_vol
    return min(max_leverage, lev)

calculate_vol_target_leverage(0.05, 0.10, 3.0)

def calculate_parametric_var(portfolio_value, daily_mean, daily_std, z_score=1.645):
    return -(daily_mean - z_score * daily_std) * portfolio_value

calculate_parametric_var(1000000.0, 0.0, 0.01, 1.645)

def calculate_historical_cvar(loss_list, alpha=0.95):
    s = sorted(loss_list)
    cutoff = int(len(s) * alpha)
    tail = s[cutoff:]
    if not tail:
        return s[-1]
    return sum(tail) / len(tail)

calculate_historical_cvar(list(range(1, 101)), 0.95)
